#!/usr/bin/env python3
"""Apply cetusproEQ 0.5.11 GUI-only source after v0.5.10.1.
Preserve exact Processor/filter/Cetus Link DSP SHA256 digests.
"""
from pathlib import Path
import re,json,lzma,base64,hashlib

PAYLOAD=""
methods=json.loads(lzma.decompress(base64.b64decode(PAYLOAD)))

def replace_method(source,name,body):
    if name=="CetusproEQAudioProcessorEditor":
        pattern=r"CetusproEQAudioProcessorEditor::CetusproEQAudioProcessorEditor\s*\("
    elif name=="CetusLookAndFeel::CetusLookAndFeel":
        pattern=r"CetusproEQAudioProcessorEditor::CetusLookAndFeel::CetusLookAndFeel\s*\("
    else:
        pattern=r"(?:void|juce::Font)\s+CetusproEQAudioProcessorEditor::(?:CetusLookAndFeel::)?"+re.escape(name)+r"\s*\("
    match=re.search(pattern,source)
    if not match:
        raise SystemExit("Missing GUI function: "+name)
    start=source.rfind("\n",0,match.start())+1
    opening=source.index("{",match.end())
    depth=0
    for end in range(opening,len(source)):
        if source[end]=="{": depth+=1
        elif source[end]=="}":
            depth-=1
            if depth==0:
                return source[:start]+body+source[end+1:]
    raise SystemExit("Unbalanced GUI method: "+name)

path=Path("Source/PluginEditor.cpp")
source=path.read_text(encoding="utf-8")
for name,body in methods.items():
    source=replace_method(source,name,body)
    print("Updated UI method:",name)
path.write_text(source,encoding="utf-8")

cpath=Path("CMakeLists.txt")
cm=cpath.read_text(encoding="utf-8")
assert cm.count("VERSION 0.5.10.1")==1, "Unexpected base version"
cpath.write_text(cm.replace("VERSION 0.5.10.1","VERSION 0.5.11",1),encoding="utf-8")

expected={
"Source/PluginProcessor.cpp":"e72d5fda9c31fbc8cdb4223be3c4ddddaa9699d9905ce4e55fe4b7c6735ab6d4",
"Source/PluginProcessor.h":"2e698fc4c3aa124b426add504cca1d8dfd7d4f4340b642b46fdffc56ebf90695",
"Source/CetusEQFilters.h":"7ce62811577d1f78606e1828fa322dc0c8b5da1dc1eff33b26e4d4e720a4f329",
"Source/CetusLink.h":"0d774b5846f22e537a185cea15a96bde3008c2fc28984d9bd593240fc324eefc",
}
for filename,sha in expected.items():
    digest=hashlib.sha256(Path(filename).read_bytes()).hexdigest()
    if digest!=sha: raise SystemExit("DSP SHA256 mismatch: "+filename)
print("v0.5.11 GUI patch and immutable DSP SHA256 checks passed")
